+fn cmd_spec_compare(cli: &Cli, from: &Path, package: &Path, basis: Option<&str>, write: bool) -> Result<()> {
+    let root = workspace_root(cli);
+    let from = if from.is_absolute() { from.to_path_buf() } else { root.join(from) };
+    let mut plan = crate::spec::refinement::prepare(&root, &from, package)?;
+    if write || cli.save_plan {
+        anyhow::ensure!(basis == plan.report["basis"].as_str(), "comparison execution needs the unchanged complete review basis");
+    }
+    let changes = plan.files.iter().map(|file| crate::edit::FileChange {
+        path: &file.path, original: &file.original, updated: &file.updated,
+    }).collect::<Vec<_>>();
+    let transaction = persist_changes(cli, &changes, write, "model-comparison-v1")?;
+    plan.report["transaction"] = serde_json::json!(transaction);
+    plan.report["applied"] = serde_json::json!(write && transaction.is_some());
+    plan.report["saved"] = serde_json::json!(cli.save_plan && transaction.is_some());
+    println!("{}", serde_json::to_string_pretty(&plan.report)?);
+    Ok(())
+}
